local function geometry(kind,u,v)
 local c,s=math.cos,math.sin
 if kind==1 then return (.62+.25*c(v))*c(u),(.62+.25*c(v))*s(u),.25*s(v)
 elseif kind==2 then
  local a,b,z=c(v)*c(u),c(v)*s(u),s(v);return b*z,a*z,a*b
